// post: sort elements into desending order 
public void sort(ArrayList<Integer> data){ 
  int max, temp; 
  int lim = data.size() - 1; 
  for(int i = 0; i < lim; i++){ 
    max = i; 
    for(int j = i + 1; j < data.size(); j++) 
      if( data.get(j) > data.get(max) ) 
        max = j; 
    if( i != max ){ 
      temp = data.remove(i); 
      data.add(i, data.remove(max - 1) ); 
      data.add(max, temp); 
    } 
  } 
}   
